use std::env;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::Path;
use std::process::{Command, Stdio, ExitStatus};
use std::collections::HashMap;

mod lexer;
mod parser;
mod executor;

use executor::Executor;
use parser::{Parser, AstNode};

const VERSION: &str = "0.4.2";

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut command = None;
    let mut file = None;
    let mut login = false;
    let mut norc = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--version" => {
                println!("{}", VERSION);
                std::process::exit(0);
            }
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-c" => {
                if i + 1 < args.len() {
                    command = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("Error: -c requires an argument");
                    std::process::exit(1);
                }
            }
            "-l" | "--login" => {
                login = true;
                i += 1;
            }
            "--norc" => {
                norc = true;
                i += 1;
            }
            _ => {
                if !args[i].starts_with('-') {
                    file = Some(args[i].clone());
                    i += 1;
                } else {
                    eprintln!("Error: unknown flag {}", args[i]);
                    std::process::exit(1);
                }
            }
        }
    }

    let mut executor = Executor::new();

    if let Some(cmd) = command {
        match execute_command(&cmd, &mut executor) {
            Ok(_) => {},
            Err(e) => {
                eprintln!("nsh: {}", e);
                std::process::exit(1);
            }
        }
    } else if let Some(file_path) = file {
        match execute_file(&file_path, &mut executor) {
            Ok(_) => {},
            Err(e) => {
                eprintln!("nsh: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        // Interactive mode
        interactive(&mut executor);
    }
}

fn print_help() {
    println!("nsh {}
A command-line shell that focuses on performance and productivity.

USAGE:
    executable [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
    -c <command>        The command to be executed

ARGS:
    <FILE>    The file to be executed", VERSION);
}

fn execute_command(cmd: &str, executor: &mut Executor) -> Result<(), String> {
    let parser = Parser::new(cmd);
    let ast = parser.parse()?;
    executor.execute(&ast)?;
    Ok(())
}

fn execute_file(path: &str, executor: &mut Executor) -> Result<(), String> {
    let contents = fs::read_to_string(path)
        .map_err(|e| format!("failed to read file {}: {}", path, e))?;
    let parser = Parser::new(&contents);
    let ast = parser.parse()?;
    executor.execute(&ast)?;
    Ok(())
}

fn interactive(executor: &mut Executor) {
    // For now, just provide a simple interactive loop
    let stdin = io::stdin();
    let reader = stdin.lock();

    for line in reader.lines() {
        if let Ok(cmd) = line {
            if cmd.trim().is_empty() {
                continue;
            }
            let parser = Parser::new(&cmd);
            match parser.parse() {
                Ok(ast) => {
                    if let Err(e) = executor.execute(&ast) {
                        eprintln!("nsh: {}", e);
                    }
                }
                Err(e) => {
                    eprintln!("nsh: {}", e);
                }
            }
        }
    }
}
