#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Word(String),
    Pipe,
    And,
    Or,
    Semicolon,
    LeftParen,
    RightParen,
    LeftBrace,
    RightBrace,
    GreaterThan,
    LessThan,
    GreaterGreaterThan,
    GreaterAmpersand,
    LessAmpersand,
    If,
    Then,
    Else,
    Elif,
    Fi,
    For,
    In,
    Do,
    Done,
    While,
    Case,
    Esac,
    Function,
    Break,
    Continue,
    Return,
    EOF,
}

pub struct Lexer {
    input: Vec<char>,
    pos: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    pub fn tokenize(&mut self) -> Result<Vec<Token>, String> {
        let mut tokens = Vec::new();

        while self.pos < self.input.len() {
            self.skip_whitespace_and_comments();
            if self.pos >= self.input.len() {
                break;
            }

            let ch = self.input[self.pos];

            if ch == '|' {
                if self.peek_ahead(1) == Some('|') {
                    self.pos += 2;
                    tokens.push(Token::Or);
                } else {
                    self.pos += 1;
                    tokens.push(Token::Pipe);
                }
            } else if ch == '&' {
                if self.peek_ahead(1) == Some('&') {
                    self.pos += 2;
                    tokens.push(Token::And);
                } else {
                    self.pos += 1;
                    // Background is handled elsewhere
                }
            } else if ch == ';' {
                self.pos += 1;
                tokens.push(Token::Semicolon);
            } else if ch == '(' {
                self.pos += 1;
                tokens.push(Token::LeftParen);
            } else if ch == ')' {
                self.pos += 1;
                tokens.push(Token::RightParen);
            } else if ch == '{' {
                self.pos += 1;
                tokens.push(Token::LeftBrace);
            } else if ch == '}' {
                self.pos += 1;
                tokens.push(Token::RightBrace);
            } else if ch == '>' {
                if self.peek_ahead(1) == Some('>') {
                    self.pos += 2;
                    tokens.push(Token::GreaterGreaterThan);
                } else if self.peek_ahead(1) == Some('&') {
                    self.pos += 2;
                    tokens.push(Token::GreaterAmpersand);
                } else {
                    self.pos += 1;
                    tokens.push(Token::GreaterThan);
                }
            } else if ch == '<' {
                if self.peek_ahead(1) == Some('&') {
                    self.pos += 2;
                    tokens.push(Token::LessAmpersand);
                } else {
                    self.pos += 1;
                    tokens.push(Token::LessThan);
                }
            } else if ch == '"' || ch == '\'' {
                let word = self.read_quoted_string()?;
                tokens.push(Token::Word(word));
            } else {
                let word = self.read_word()?;
                let token = match word.as_str() {
                    "if" => Token::If,
                    "then" => Token::Then,
                    "else" => Token::Else,
                    "elif" => Token::Elif,
                    "fi" => Token::Fi,
                    "for" => Token::For,
                    "in" => Token::In,
                    "do" => Token::Do,
                    "done" => Token::Done,
                    "while" => Token::While,
                    "case" => Token::Case,
                    "esac" => Token::Esac,
                    "function" => Token::Function,
                    "break" => Token::Break,
                    "continue" => Token::Continue,
                    "return" => Token::Return,
                    _ => Token::Word(word),
                };
                tokens.push(token);
            }
        }

        tokens.push(Token::EOF);
        Ok(tokens)
    }

    fn skip_whitespace_and_comments(&mut self) {
        while self.pos < self.input.len() {
            let ch = self.input[self.pos];
            if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
                self.pos += 1;
            } else if ch == '#' {
                // Skip comment until end of line
                while self.pos < self.input.len() && self.input[self.pos] != '\n' {
                    self.pos += 1;
                }
            } else {
                break;
            }
        }
    }

    fn peek_ahead(&self, offset: usize) -> Option<char> {
        if self.pos + offset < self.input.len() {
            Some(self.input[self.pos + offset])
        } else {
            None
        }
    }

    fn read_quoted_string(&mut self) -> Result<String, String> {
        let quote_char = self.input[self.pos];
        self.pos += 1;
        let mut result = String::new();

        while self.pos < self.input.len() && self.input[self.pos] != quote_char {
            if self.input[self.pos] == '\\' && self.pos + 1 < self.input.len() {
                self.pos += 1;
                result.push(self.input[self.pos]);
                self.pos += 1;
            } else {
                result.push(self.input[self.pos]);
                self.pos += 1;
            }
        }

        if self.pos >= self.input.len() {
            return Err("Unterminated quoted string".to_string());
        }

        self.pos += 1; // Skip closing quote
        Ok(result)
    }

    fn read_word(&mut self) -> Result<String, String> {
        let mut result = String::new();
        let mut in_brace = false;
        let mut brace_count = 0;

        while self.pos < self.input.len() {
            let ch = self.input[self.pos];

            if ch == '$' && self.peek_ahead(1) == Some('{') {
                in_brace = true;
                brace_count += 1;
                result.push(ch);
                self.pos += 1;
            } else if in_brace && ch == '}' {
                brace_count -= 1;
                result.push(ch);
                self.pos += 1;
                if brace_count == 0 {
                    in_brace = false;
                }
            } else if in_brace {
                result.push(ch);
                self.pos += 1;
            } else if ch == '"' || ch == '\'' {
                let quoted = self.read_quoted_string()?;
                result.push_str(&quoted);
            } else if ch == '$' {
                // Variable expansion
                self.pos += 1;
                if self.pos < self.input.len() {
                    let var_name = self.read_variable_name();
                    result.push('$');
                    result.push_str(&var_name);
                }
            } else if ch == '\\' && self.peek_ahead(1).is_some() {
                // Escape sequence
                self.pos += 1;
                result.push(self.input[self.pos]);
                self.pos += 1;
            } else if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' 
                   || ch == '|' || ch == '&' || ch == ';' || ch == '(' || ch == ')' 
                   || ch == '<' || ch == '>' || ch == '{' || ch == '}' {
                break;
            } else {
                result.push(ch);
                self.pos += 1;
            }
        }

        Ok(result)
    }

    fn read_variable_name(&mut self) -> String {
        let mut name = String::new();
        while self.pos < self.input.len() {
            let ch = self.input[self.pos];
            if ch.is_alphanumeric() || ch == '_' {
                name.push(ch);
                self.pos += 1;
            } else {
                break;
            }
        }
        name
    }
}
