                if let Token::Word(w) = self.peek() {
                    patterns.push(w.clone());
                    self.consume();
                    if self.peek() == &Token::Or {
                        self.consume();
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }

            // Expect closing paren
            if self.peek() == &Token::LeftParen {
                self.consume();
            }

            let body = self.parse_sequence()?;

            cases.push((patterns, body));

            // Skip semicolons
            while self.peek() == &Token::Semicolon {
                self.consume();
            }
        }

        self.expect(Token::Esac)?;

        Ok(AstNode::CaseStatement { expr, cases })
    }

    fn parse_function(&mut self) -> Result<AstNode, String> {
        self.expect(Token::Function)?;

        let name = match self.peek() {
            Token::Word(w) => {
                let n = w.clone();
                self.consume();
                n
            }
            _ => return Err("expected function name".to_string()),
        };

        // Skip optional parens
        if self.peek() == &Token::LeftParen {
            self.consume();
            self.expect(Token::RightParen)?;
        }

        let body = if self.peek() == &Token::LeftBrace {
            self.consume();
            let b = self.parse_sequence()?;
            self.expect(Token::RightBrace)?;
            Box::new(b)
        } else {
            return Err("expected function body".to_string());
        };

        Ok(AstNode::FunctionDef { name, body })
    }

    fn parse_subshell(&mut self) -> Result<AstNode, String> {
        self.expect(Token::LeftParen)?;
        let cmd = self.parse_sequence()?;
        self.expect(Token::RightParen)?;
        Ok(AstNode::Subshell(Box::new(cmd)))
    }

    fn parse_group(&mut self) -> Result<AstNode, String> {
        self.expect(Token::LeftBrace)?;
        let cmd = self.parse_sequence()?;
        self.expect(Token::RightBrace)?;
        Ok(AstNode::Group(Box::new(cmd)))
    }

    fn parse_command(&mut self) -> Result<AstNode, String> {
        let mut name = String::new();
        let mut args = Vec::new();
        let mut redirects = Vec::new();

        // Handle builtins or commands
        match self.peek() {
            Token::Word(w) => {
                name = w.clone();
                self.consume();
            }
            _ => return Err("expected command".to_string()),
        }

        // Parse arguments and redirects
        loop {
            match self.peek() {
                Token::Word(w) => {
                    args.push(w.clone());
                    self.consume();
                }
                Token::GreaterThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 1,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                Token::GreaterGreaterThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 1,
                            to: file.clone(),
                            append: true,
                        });
                        self.consume();
                    }
                }
                Token::LessThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 0,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                Token::GreaterAmpersand => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 2,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                _ => break,
            }
        }

        Ok(AstNode::Command { name, args, redirects })
    }

    fn peek(&self) -> &Token {
        self.tokens.front().unwrap_or(&Token::EOF)
    }

    fn consume(&mut self) {
        if !self.is_at_end() {
            self.tokens.pop_front();
        }
    }

    fn expect(&mut self, expected: Token) -> Result<(), String> {
        if std::mem::discriminant(self.peek()) == std::mem::discriminant(&expected) {
            self.consume();
            Ok(())
        } else {
            Err(format!("expected {:?}, got {:?}", expected, self.peek()))
        }
    }

    fn is_at_end(&self) -> bool {
        matches!(self.peek(), Token::EOF)
    }
}
