use crate::parser::{AstNode, Redirect};
use std::collections::HashMap;
use std::env;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Write, BufRead, BufReader};
use std::os::unix::io::FromRawFd;
use std::process::{Command, Stdio, ChildStdin, ChildStdout};
use std::path::Path;

pub struct Executor {
    variables: HashMap<String, String>,
    functions: HashMap<String, AstNode>,
    break_flag: bool,
    continue_flag: bool,
    return_flag: bool,
    last_status: i32,
}

impl Executor {
    pub fn new() -> Self {
        let mut vars = HashMap::new();
        // Initialize some common variables
        if let Ok(home) = env::var("HOME") {
            vars.insert("HOME".to_string(), home);
        }
        if let Ok(path) = env::var("PATH") {
            vars.insert("PATH".to_string(), path);
        }

        Executor {
            variables: vars,
            functions: HashMap::new(),
            break_flag: false,
            continue_flag: false,
            return_flag: false,
            last_status: 0,
        }
    }

    pub fn execute(&mut self, node: &AstNode) -> Result<(), String> {
        match node {
            AstNode::Command {
                name,
                args,
                redirects,
            } => {
                self.execute_command(name, args, redirects)?;
            }
            AstNode::Pipe(commands) => {
                self.execute_pipe(commands)?;
            }
            AstNode::And(nodes) => {
                for n in nodes {
                    self.execute(n)?;
                    if self.last_status != 0 {
                        break;
                    }
                }
            }
            AstNode::Or(nodes) => {
                for n in nodes {
                    self.execute(n)?;
                    if self.last_status == 0 {
                        break;
                    }
                }
            }
            AstNode::Sequence(commands) => {
                for cmd in commands {
                    self.execute(cmd)?;
                    if self.break_flag || self.continue_flag || self.return_flag {
                        break;
                    }
                }
            }
            AstNode::IfStatement {
                condition,
                then_part,
                else_part,
            } => {
                self.execute(condition)?;
                if self.last_status == 0 {
                    self.execute(then_part)?;
                } else if let Some(else_p) = else_part {
                    self.execute(else_p)?;
                }
            }
            AstNode::ForLoop { var, items, body } => {
                for item in items {
                    let expanded = self.expand_word(item)?;
                    for e in expanded {
                        self.variables.insert(var.clone(), e);
                        self.execute(body)?;
                        if self.break_flag {
                            self.break_flag = false;
                            break;
                        }
                        if self.continue_flag {
                            self.continue_flag = false;
                            continue;
                        }
                        if self.return_flag {
                            break;
                        }
                    }
                    if self.break_flag {
                        self.break_flag = false;
                        break;
                    }
                }
            }
            AstNode::WhileLoop { condition, body } => {
                loop {
                    self.execute(condition)?;
                    if self.last_status != 0 {
                        break;
                    }
                    self.execute(body)?;
                    if self.break_flag {
                        self.break_flag = false;
                        break;
                    }
                    if self.continue_flag {
                        self.continue_flag = false;
                        continue;
                    }
                }
            }
            AstNode::CaseStatement { expr, cases } => {
                let expanded_expr = self.expand_word(expr)?;
                if let Some(expr_val) = expanded_expr.first() {
                    for (patterns, body) in cases {
                        for pattern in patterns {
                            if self.glob_match(pattern, expr_val) {
                                self.execute(body)?;
                                return Ok(());
                            }
                        }
                    }
                }
            }
            AstNode::FunctionDef { name, body } => {
                self.functions.insert(name.clone(), (**body).clone());
            }
            AstNode::Subshell(cmd) => {
                // Fork execution (simplified - don't actually fork for now)
                self.execute(cmd)?;
            }
            AstNode::Group(cmd) => {
                self.execute(cmd)?;
            }
            AstNode::Break => {
                self.break_flag = true;
            }
            AstNode::Continue => {
                self.continue_flag = true;
            }
            AstNode::Return => {
                self.return_flag = true;
            }
        }
        Ok(())
    }

    fn execute_command(&mut self, name: &str, args: &[String], redirects: &[Redirect]) -> Result<(), String> {
        // Handle builtins
        match name {
            "echo" => self.builtin_echo(args)?,
            "cd" => self.builtin_cd(args)?,
            "export" => self.builtin_export(args)?,
            "unset" => self.builtin_unset(args)?,
            "set" => self.builtin_set(args)?,
            "alias" => self.builtin_alias(args)?,
            "test" => self.builtin_test(args)?,
            _ => {
                // Check if it's a function
                if let Some(func_body) = self.functions.get(name).cloned() {
                    self.execute(&func_body)?;
                } else {
                    // Execute external command
                    self.execute_external(name, args, redirects)?;
                }
            }
        }
        Ok(())
    }

    fn execute_external(&mut self, cmd: &str, args: &[String], redirects: &[Redirect]) -> Result<(), String> {
        let mut command = Command::new(cmd);

        for arg in args {
            let expanded = self.expand_word(arg)?;
            for e in expanded {
                command.arg(e);
            }
        }

        // Apply redirects
        for redirect in redirects {
            match redirect.from {
                0 => {
                    let file = File::open(&redirect.to)
                        .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stdin(file);
                }
                1 => {
                    let file = if redirect.append {
                        OpenOptions::new()
                            .append(true)
                            .create(true)
                            .open(&redirect.to)
                    } else {
                        File::create(&redirect.to)
                    }
                    .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stdout(file);
                }
                2 => {
                    let file = if redirect.append {
                        OpenOptions::new()
                            .append(true)
                            .create(true)
                            .open(&redirect.to)
                    } else {
                        File::create(&redirect.to)
                    }
                    .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stderr(file);
                }
                _ => {}
            }
        }

        let output = command
            .output()
            .map_err(|e| format!("{}: {}", cmd, e))?;

        if !output.stdout.is_empty() {
            print!("{}", String::from_utf8_lossy(&output.stdout));
        }
        if !output.stderr.is_empty() {
            eprint!("{}", String::from_utf8_lossy(&output.stderr));
        }

        self.last_status = output.status.code().unwrap_or(1);
        Ok(())
    }

    fn execute_pipe(&mut self, commands: &[AstNode]) -> Result<(), String> {
        // This is simplified - a full implementation would create processes
        // For now, just execute commands in sequence and hope they work
        for cmd in commands {
            self.execute(cmd)?;
        }
        Ok(())
    }

    fn expand_word(&mut self, word: &str) -> Result<Vec<String>, String> {
        let mut result = String::new();
        let chars: Vec<char> = word.chars().collect();
        let mut i = 0;

        while i < chars.len() {
            if chars[i] == '$' && i + 1 < chars.len() {
                if chars[i + 1] == '{' {
                    // ${VAR} expansion
                    i += 2;
                    let mut var_name = String::new();
                    while i < chars.len() && chars[i] != '}' {
                        var_name.push(chars[i]);
                        i += 1;
                    }
                    if i < chars.len() {
                        i += 1; // Skip }
                    }
                    let var_val = self.variables.get(&var_name).cloned().unwrap_or_default();
                    result.push_str(&var_val);
                } else if chars[i + 1] == '(' {
                    // $(...) command substitution
                    i += 2;
                    let mut cmd = String::new();
                    let mut paren_count = 1;
                    while i < chars.len() && paren_count > 0 {
                        if chars[i] == '(' {
                            paren_count += 1;
                        } else if chars[i] == ')' {
                            paren_count -= 1;
                            if paren_count == 0 {
                                break;
                            }
                        }
                        cmd.push(chars[i]);
                        i += 1;
                    }
                    i += 1; // Skip closing )
                    let output = self.run_command_substitution(&cmd)?;
                    result.push_str(&output);
                } else if chars[i + 1].is_alphanumeric() || chars[i + 1] == '_' {
                    // $VAR expansion
                    i += 1;
                    let mut var_name = String::new();
                    while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                        var_name.push(chars[i]);
                        i += 1;
                    }
                    let var_val = self.variables.get(&var_name).cloned().unwrap_or_default();
                    result.push_str(&var_val);
                } else {
                    result.push(chars[i]);
                    i += 1;
                }
            } else if chars[i] == '\\' && i + 1 < chars.len() {
                i += 1;
                result.push(chars[i]);
