        let mut pattern = String::new();
        let mut i = start;

        while i < chars.len() {
            let ch = chars[i];
            if ch.is_whitespace() || ch == '|' || ch == '&' || ch == ';' 
                || ch == '>' || ch == '<' || ch == '(' || ch == ')' {
                break;
            }
            pattern.push(ch);
            i += 1;
        }

        pattern
    }

