        let output = std::process::Command::new("sh")
            .arg("-c")
            .arg(cmd)
            .output()
            .map_err(|e| e.to_string())?;

        let result = String::from_utf8_lossy(&output.stdout).to_string();
        Ok(result.trim_end().to_string())
    }

    fn glob_expand(&self, pattern: &str) -> Result<Vec<String>, String> {
        // Use ls to do the glob expansion
        let output = std::process::Command::new("ls")
            .arg("-d")
            .arg(pattern)
            .output()
            .map_err(|e| e.to_string())?;

        if output.status.success() {
            let result = String::from_utf8_lossy(&output.stdout);
            let matches: Vec<String> = result
                .lines()
                .map(|l| l.to_string())
                .collect();
            if matches.is_empty() {
                Err("no matches".to_string())
            } else {
                Ok(matches)
            }
        } else {
            Err("no matches".to_string())
        }
    }

    fn glob_match(&self, pattern: &str, text: &str) -> bool {
        // Simple glob matching
        let pat_chars: Vec<char> = pattern.chars().collect();
        let text_chars: Vec<char> = text.chars().collect();
        self.glob_match_recursive(&pat_chars, 0, &text_chars, 0)
    }

    fn glob_match_recursive(&self, pattern: &[char], pi: usize, text: &[char], ti: usize) -> bool {
        if pi >= pattern.len() {
            return ti >= text.len();
        }

        match pattern[pi] {
            '*' => {
                if pi + 1 >= pattern.len() {
                    return true;
                }
                for i in ti..=text.len() {
                    if self.glob_match_recursive(pattern, pi + 1, text, i) {
                        return true;
                    }
                }
                false
            }
            '?' => {
                if ti >= text.len() {
                    false
                } else {
                    self.glob_match_recursive(pattern, pi + 1, text, ti + 1)
                }
            }
            _ => {
                if ti >= text.len() || pattern[pi] != text[ti] {
                    false
                } else {
                    self.glob_match_recursive(pattern, pi + 1, text, ti + 1)
                }
            }
        }
    }

    fn builtin_echo(&mut self, args: &[String]) -> Result<(), String> {
        let mut output = String::new();
        for arg in args {
            let expanded = self.expand_word(arg)?;
            for (i, e) in expanded.iter().enumerate() {
                if i > 0 {
                    output.push(' ');
                }
                output.push_str(e);
            }
        }
        println!("{}", output);
        self.last_status = 0;
        Ok(())
    }

    fn builtin_cd(&mut self, args: &[String]) -> Result<(), String> {
        let path = if args.is_empty() {
            self.variables.get("HOME").cloned().unwrap_or_else(|| "/".to_string())
        } else {
            args[0].clone()
        };

        env::set_current_dir(&path)
            .map_err(|e| format!("cd: {}", e))?;

        self.last_status = 0;
        Ok(())
    }

    fn builtin_export(&mut self, args: &[String]) -> Result<(), String> {
        for arg in args {
            if let Some(eq_pos) = arg.find('=') {
                let name = &arg[..eq_pos];
                let value = &arg[eq_pos + 1..];
                self.variables.insert(name.to_string(), value.to_string());
                env::set_var(name, value);
            } else {
                if let Some(val) = self.variables.get(arg) {
                    env::set_var(arg, val);
                }
            }
        }
        self.last_status = 0;
        Ok(())
    }

    fn builtin_unset(&mut self, args: &[String]) -> Result<(), String> {
        for arg in args {
            self.variables.remove(arg);
        }
        self.last_status = 0;
        Ok(())
    }

    fn builtin_set(&mut self, args: &[String]) -> Result<(), String> {
        // For now, just handle simple assignment
        for arg in args {
            if let Some(eq_pos) = arg.find('=') {
                let name = &arg[..eq_pos];
                let value = &arg[eq_pos + 1..];
                self.variables.insert(name.to_string(), value.to_string());
            }
        }
        self.last_status = 0;
        Ok(())
    }

    fn builtin_alias(&mut self, _args: &[String]) -> Result<(), String> {
        // Aliases not fully implemented
        self.last_status = 0;
        Ok(())
    }

    fn builtin_test(&mut self, args: &[String]) -> Result<(), String> {
        // Simple test implementation
        if args.is_empty() {
            self.last_status = 1;
            return Ok(());
        }

        let result = match args[0].as_str() {
            "-f" => {
                if args.len() > 1 {
                    Path::new(&args[1]).is_file()
                } else {
                    false
                }
            }
            "-d" => {
                if args.len() > 1 {
                    Path::new(&args[1]).is_dir()
                } else {
                    false
                }
            }
            "-e" => {
                if args.len() > 1 {
                    Path::new(&args[1]).exists()
                } else {
                    false
                }
            }
            "-eq" => {
                if args.len() > 2 {
                    if let (Ok(a), Ok(b)) = (args[1].parse::<i64>(), args[2].parse::<i64>()) {
                        a == b
                    } else {
                        false
                    }
                } else {
                    false
                }
            }
            _ => false,
        };

        self.last_status = if result { 0 } else { 1 };
        Ok(())
    }
}
