use crate::parser::{AstNode, Redirect};
use std::collections::HashMap;
use std::env;
use std::fs::{File, OpenOptions};
use std::io::Write;
use std::process::{Command, Stdio};
use std::path::Path;
use std::os::unix::io::{FromRawFd, IntoRawFd};

pub struct Executor {
    variables: HashMap<String, String>,
    functions: HashMap<String, AstNode>,
    break_flag: bool,
    continue_flag: bool,
    return_flag: bool,
    last_status: i32,
}

impl Executor {
    pub fn new() -> Self {
        let mut vars = HashMap::new();
        // Initialize some common variables
        if let Ok(home) = env::var("HOME") {
            vars.insert("HOME".to_string(), home);
        }
        if let Ok(path) = env::var("PATH") {
            vars.insert("PATH".to_string(), path);
        }

        Executor {
            variables: vars,
            functions: HashMap::new(),
            break_flag: false,
            continue_flag: false,
            return_flag: false,
            last_status: 0,
        }
    }

    pub fn execute(&mut self, node: &AstNode) -> Result<(), String> {
        match node {
            AstNode::Command {
                name,
                args,
                redirects,
            } => {
                self.execute_command(name, args, redirects)?;
            }
            AstNode::Pipe(commands) => {
                self.execute_pipe(commands)?;
            }
            AstNode::And(nodes) => {
                for n in nodes {
                    self.execute(n)?;
                    if self.last_status != 0 {
                        break;
                    }
                }
            }
            AstNode::Or(nodes) => {
                for n in nodes {
                    self.execute(n)?;
                    if self.last_status == 0 {
                        break;
                    }
                }
            }
            AstNode::Sequence(commands) => {
                for cmd in commands {
                    self.execute(cmd)?;
                    if self.break_flag || self.continue_flag || self.return_flag {
                        break;
                    }
                }
            }
            AstNode::IfStatement {
                condition,
                then_part,
                else_part,
            } => {
                self.execute(condition)?;
                if self.last_status == 0 {
                    self.execute(then_part)?;
                } else if let Some(else_p) = else_part {
                    self.execute(else_p)?;
                }
            }
            AstNode::ForLoop { var, items, body } => {
                for item in items {
                    let expanded = self.expand_word(item)?;
                    for e in expanded {
                        self.variables.insert(var.clone(), e);
                        self.execute(body)?;
                        if self.break_flag {
                            self.break_flag = false;
                            break;
                        }
                        if self.continue_flag {
                            self.continue_flag = false;
                            continue;
                        }
                        if self.return_flag {
                            break;
                        }
                    }
                    if self.break_flag {
                        self.break_flag = false;
                        break;
                    }
                }
            }
            AstNode::WhileLoop { condition, body } => {
                loop {
                    self.execute(condition)?;
                    if self.last_status != 0 {
                        break;
                    }
                    self.execute(body)?;
                    if self.break_flag {
                        self.break_flag = false;
                        break;
                    }
                    if self.continue_flag {
                        self.continue_flag = false;
                        continue;
                    }
                }
            }
            AstNode::CaseStatement { expr, cases } => {
                let expanded_expr = self.expand_word(expr)?;
                if let Some(expr_val) = expanded_expr.first() {
                    for (patterns, body) in cases {
                        for pattern in patterns {
                            if self.glob_match(pattern, expr_val) {
                                self.execute(body)?;
                                return Ok(());
                            }
                        }
                    }
                }
            }
            AstNode::FunctionDef { name, body } => {
                self.functions.insert(name.clone(), (**body).clone());
            }
            AstNode::Subshell(cmd) => {
                // Fork execution (simplified - don't actually fork for now)
                self.execute(cmd)?;
            }
            AstNode::Group(cmd) => {
                self.execute(cmd)?;
            }
            AstNode::Break => {
                self.break_flag = true;
            }
            AstNode::Continue => {
                self.continue_flag = true;
            }
            AstNode::Return => {
                self.return_flag = true;
            }
        }
        Ok(())
    }

    fn execute_command(&mut self, name: &str, args: &[String], redirects: &[Redirect]) -> Result<(), String> {
        // Handle builtins
        match name {
            "echo" => self.builtin_echo(args)?,
            "cd" => self.builtin_cd(args)?,
            "export" => self.builtin_export(args)?,
            "unset" => self.builtin_unset(args)?,
            "set" => self.builtin_set(args)?,
            "alias" => self.builtin_alias(args)?,
            "test" => self.builtin_test(args)?,
            _ => {
                // Check if it's a function
                if let Some(func_body) = self.functions.get(name).cloned() {
                    self.execute(&func_body)?;
                } else {
                    // Execute external command
                    self.execute_external(name, args, redirects)?;
                }
            }
        }
        Ok(())
    }

    fn execute_external(&mut self, cmd: &str, args: &[String], redirects: &[Redirect]) -> Result<(), String> {
        let mut command = Command::new(cmd);

        for arg in args {
            let expanded = self.expand_word(arg)?;
            for e in expanded {
                command.arg(e);
            }
        }

        // Apply redirects
        let mut stdin_redirect = false;
        let mut stdout_redirect = false;
        let mut stderr_redirect = false;

        for redirect in redirects {
            match redirect.from {
                0 => {
                    let file = File::open(&redirect.to)
                        .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stdin(file);
                    stdin_redirect = true;
                }
                1 => {
                    let file = if redirect.append {
                        OpenOptions::new()
                            .append(true)
                            .create(true)
                            .open(&redirect.to)
                    } else {
                        File::create(&redirect.to)
                    }
                    .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stdout(file);
                    stdout_redirect = true;
                }
                2 => {
                    let file = if redirect.append {
                        OpenOptions::new()
                            .append(true)
                            .create(true)
                            .open(&redirect.to)
                    } else {
                        File::create(&redirect.to)
                    }
                    .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stderr(file);
                    stderr_redirect = true;
                }
                _ => {}
            }
        }

        let output = command
            .output()
            .map_err(|e| format!("{}: {}", cmd, e))?;

        if !stdout_redirect && !output.stdout.is_empty() {
            print!("{}", String::from_utf8_lossy(&output.stdout));
        }
        if !stderr_redirect && !output.stderr.is_empty() {
            eprint!("{}", String::from_utf8_lossy(&output.stderr));
        }

        self.last_status = output.status.code().unwrap_or(1);
        Ok(())
    }

    fn execute_pipe(&mut self, commands: &[AstNode]) -> Result<(), String> {
        if commands.is_empty() {
            return Ok(());
        }

        if commands.len() == 1 {
            return self.execute(&commands[0]);
        }

        // Extract command info from AST nodes
        let mut cmd_specs = Vec::new();
        for cmd in commands {
            if let AstNode::Command { name, args, redirects } = cmd {
                cmd_specs.push((name.clone(), args.clone(), redirects.clone()));
            } else {
                return Err("pipe only works with simple commands".to_string());
            }
        }

        // Create all processes
        let mut children = Vec::new();
        let mut stdin = Stdio::inherit();

        for (i, (name, args, redirects)) in cmd_specs.iter().enumerate() {
            let mut command = Command::new(name);
            command.stdin(stdin);

            // Setup stdout
            if i < cmd_specs.len() - 1 {
                // Pipe to next command
                command.stdout(Stdio::piped());
            } else {
                // Last command inherits stdout
                command.stdout(Stdio::inherit());
            }

            // Expand args
            for arg in args {
                let expanded = self.expand_word(arg)?;
                for e in expanded {
                    command.arg(e);
                }
            }

            let mut child = command
                .spawn()
                .map_err(|e| format!("{}: {}", name, e))?;

            // Get stdout for next command
            if i < cmd_specs.len() - 1 {
                stdin = Stdio::from(child.stdout.take().ok_or("failed to get child stdout")?);
            }

            children.push(child);
        }

        // Wait for all children
        let mut last_status = 0;
        for mut child in children {
            let status = child.wait()
                .map_err(|e| format!("wait error: {}", e))?;
            last_status = status.code().unwrap_or(1);
        }

        self.last_status = last_status;
        Ok(())
    }

    fn expand_word(&mut self, word: &str) -> Result<Vec<String>, String> {
        let mut result = String::new();
        let chars: Vec<char> = word.chars().collect();
        let mut i = 0;

        while i < chars.len() {
            if chars[i] == '$' && i + 1 < chars.len() {
                if chars[i + 1] == '{' {
                    // ${VAR} expansion
                    i += 2;
                    let mut var_name = String::new();
                    while i < chars.len() && chars[i] != '}' {
                        var_name.push(chars[i]);
                        i += 1;
                    }
                    if i < chars.len() {
                        i += 1; // Skip }
                    }
                    let var_val = self.variables.get(&var_name).cloned().unwrap_or_default();
                    result.push_str(&var_val);
                } else if chars[i + 1] == '(' {
                    // $(...) command substitution
                    i += 2;
                    let mut cmd = String::new();
                    let mut paren_count = 1;
                    while i < chars.len() && paren_count > 0 {
                        if chars[i] == '(' {
                            paren_count += 1;
                        } else if chars[i] == ')' {
                            paren_count -= 1;
                            if paren_count == 0 {
                                break;
                            }
                        }
                        cmd.push(chars[i]);
                        i += 1;
                    }
                    i += 1; // Skip closing )
                    let output = self.run_command_substitution(&cmd)?;
                    result.push_str(&output);
                } else if chars[i + 1].is_alphanumeric() || chars[i + 1] == '_' || chars[i + 1] == '?' {
                    // $VAR or $? expansion
                    i += 1;
                    if chars[i] == '?' {
                        result.push_str(&self.last_status.to_string());
                        i += 1;
                    } else {
                        let mut var_name = String::new();
                        while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                            var_name.push(chars[i]);
                            i += 1;
                        }
                        let var_val = self.variables.get(&var_name).cloned().unwrap_or_default();
                        result.push_str(&var_val);
                    }
                } else {
                    result.push(chars[i]);
                    i += 1;
                }
            } else if chars[i] == '\\' && i + 1 < chars.len() {
                i += 1;
                result.push(chars[i]);
                i += 1;
            } else if chars[i] == '*' || chars[i] == '?' {
                // Glob pattern
                let glob_part = self.collect_glob_pattern(&chars, i);
                return self.glob_expand(&glob_part);
            } else {
                result.push(chars[i]);
                i += 1;
            }
        }

        Ok(vec![result])
    }

    fn collect_glob_pattern(&self, chars: &[char], start: usize) -> String {
        let mut pattern = String::new();
        let mut i = start;

        while i < chars.len() {
            let ch = chars[i];
            if ch.is_whitespace() || ch == '|' || ch == '&' || ch == ';' 
                || ch == '>' || ch == '<' || ch == '(' || ch == ')' {
                break;
            }
            pattern.push(ch);
            i += 1;
        }

        pattern
    }

    fn run_command_substitution(&mut self, cmd: &str) -> Result<String, String> {
        let output = std::process::Command::new("sh")
            .arg("-c")
            .arg(cmd)
            .output()
            .map_err(|e| e.to_string())?;

        let result = String::from_utf8_lossy(&output.stdout).to_string();
        Ok(result.trim_end().to_string())
    }

    fn glob_expand(&self, pattern: &str) -> Result<Vec<String>, String> {
        // Use ls to do the glob expansion
        let output = std::process::Command::new("ls")
            .arg("-d")
            .arg(pattern)
            .output()
            .map_err(|e| e.to_string())?;

        if output.status.success() {
            let result = String::from_utf8_lossy(&output.stdout);
            let matches: Vec<String> = result
                .lines()
                .map(|l| l.to_string())
                .collect();
            if matches.is_empty() {
                Err("no matches".to_string())
            } else {
                Ok(matches)
            }
        } else {
            Err("no matches".to_string())
        }
    }

    fn glob_match(&self, pattern: &str, text: &str) -> bool {
        // Simple glob matching
        let pat_chars: Vec<char> = pattern.chars().collect();
        let text_chars: Vec<char> = text.chars().collect();
        self.glob_match_recursive(&pat_chars, 0, &text_chars, 0)
    }

    fn glob_match_recursive(&self, pattern: &[char], pi: usize, text: &[char], ti: usize) -> bool {
        if pi >= pattern.len() {
            return ti >= text.len();
        }

        match pattern[pi] {
            '*' => {
                if pi + 1 >= pattern.len() {
                    return true;
                }
                for i in ti..=text.len() {
                    if self.glob_match_recursive(pattern, pi + 1, text, i) {
                        return true;
                    }
                }
                false
            }
            '?' => {
                if ti >= text.len() {
                    false
                } else {
                    self.glob_match_recursive(pattern, pi + 1, text, ti + 1)
                }
            }
            _ => {
                if ti >= text.len() || pattern[pi] != text[ti] {
                    false
                } else {
                    self.glob_match_recursive(pattern, pi + 1, text, ti + 1)
                }
            }
        }
    }

    fn builtin_echo(&mut self, args: &[String]) -> Result<(), String> {
        let mut output = String::new();
        for arg in args {
            let expanded = self.expand_word(arg)?;
            for (i, e) in expanded.iter().enumerate() {
                if i > 0 {
                    output.push(' ');
                }
                output.push_str(e);
            }
        }
        println!("{}", output);
        self.last_status = 0;
        Ok(())
    }

    fn builtin_cd(&mut self, args: &[String]) -> Result<(), String> {
        let path = if args.is_empty() {
            self.variables.get("HOME").cloned().unwrap_or_else(|| "/".to_string())
        } else {
            args[0].clone()
        };

        env::set_current_dir(&path)
            .map_err(|e| format!("cd: {}", e))?;

        self.last_status = 0;
        Ok(())
    }

    fn builtin_export(&mut self, args: &[String]) -> Result<(), String> {
        for arg in args {
            if let Some(eq_pos) = arg.find('=') {
                let name = &arg[..eq_pos];
                let value = &arg[eq_pos + 1..];
                self.variables.insert(name.to_string(), value.to_string());
                env::set_var(name, value);
            } else {
                if let Some(val) = self.variables.get(arg) {
                    env::set_var(arg, val);
                }
            }
        }
        self.last_status = 0;
        Ok(())
    }

    fn builtin_unset(&mut self, args: &[String]) -> Result<(), String> {
        for arg in args {
            self.variables.remove(arg);
        }
        self.last_status = 0;
        Ok(())
    }

    fn builtin_set(&mut self, args: &[String]) -> Result<(), String> {
        // For now, just handle simple assignment
        for arg in args {
            if let Some(eq_pos) = arg.find('=') {
                let name = &arg[..eq_pos];
                let value = &arg[eq_pos + 1..];
                self.variables.insert(name.to_string(), value.to_string());
            }
        }
        self.last_status = 0;
        Ok(())
    }

    fn builtin_alias(&mut self, _args: &[String]) -> Result<(), String> {
        // Aliases not fully implemented
        self.last_status = 0;
        Ok(())
    }

    fn builtin_test(&mut self, args: &[String]) -> Result<(), String> {
        // Simple test implementation
        if args.is_empty() {
            self.last_status = 1;
            return Ok(());
        }

        let result = match args[0].as_str() {
            "-f" => {
                if args.len() > 1 {
                    Path::new(&args[1]).is_file()
                } else {
                    false
                }
            }
            "-d" => {
                if args.len() > 1 {
                    Path::new(&args[1]).is_dir()
                } else {
                    false
                }
            }
            "-e" => {
                if args.len() > 1 {
                    Path::new(&args[1]).exists()
                } else {
                    false
                }
            }
            "-eq" => {
                if args.len() > 2 {
                    if let (Ok(a), Ok(b)) = (args[1].parse::<i64>(), args[2].parse::<i64>()) {
                        a == b
                    } else {
                        false
                    }
                } else {
                    false
                }
            }
            _ => false,
        };

        self.last_status = if result { 0 } else { 1 };
        Ok(())
    }
}
