use crate::parser::{AstNode, Redirect};
use std::collections::HashMap;
use std::env;
use std::fs::{File, OpenOptions};
use std::io::Write;
use std::process::{Command, Stdio};
use std::path::Path;
use std::os::unix::io::{FromRawFd, IntoRawFd};

pub struct Executor {
    variables: HashMap<String, String>,
    functions: HashMap<String, AstNode>,
    break_flag: bool,
    continue_flag: bool,
    return_flag: bool,
    last_status: i32,
}

impl Executor {
    pub fn new() -> Self {
        let mut vars = HashMap::new();
        // Initialize some common variables
        if let Ok(home) = env::var("HOME") {
            vars.insert("HOME".to_string(), home);
        }
        if let Ok(path) = env::var("PATH") {
            vars.insert("PATH".to_string(), path);
        }

        Executor {
            variables: vars,
            functions: HashMap::new(),
            break_flag: false,
            continue_flag: false,
            return_flag: false,
            last_status: 0,
        }
    }

    pub fn execute(&mut self, node: &AstNode) -> Result<(), String> {
        match node {
            AstNode::Command {
                name,
                args,
                redirects,
            } => {
                self.execute_command(name, args, redirects)?;
            }
            AstNode::Pipe(commands) => {
                self.execute_pipe(commands)?;
            }
            AstNode::And(nodes) => {
                for n in nodes {
                    self.execute(n)?;
                    if self.last_status != 0 {
                        break;
                    }
                }
            }
            AstNode::Or(nodes) => {
                for n in nodes {
                    self.execute(n)?;
                    if self.last_status == 0 {
                        break;
                    }
                }
            }
            AstNode::Sequence(commands) => {
                for cmd in commands {
                    self.execute(cmd)?;
                    if self.break_flag || self.continue_flag || self.return_flag {
                        break;
                    }
                }
            }
            AstNode::IfStatement {
                condition,
                then_part,
                else_part,
            } => {
                self.execute(condition)?;
                if self.last_status == 0 {
                    self.execute(then_part)?;
                } else if let Some(else_p) = else_part {
                    self.execute(else_p)?;
                }
            }
            AstNode::ForLoop { var, items, body } => {
                for item in items {
                    let expanded = self.expand_word(item)?;
                    for e in expanded {
                        self.variables.insert(var.clone(), e);
                        self.execute(body)?;
                        if self.break_flag {
                            self.break_flag = false;
                            break;
                        }
                        if self.continue_flag {
                            self.continue_flag = false;
                            continue;
                        }
                        if self.return_flag {
                            break;
                        }
                    }
                    if self.break_flag {
                        self.break_flag = false;
                        break;
                    }
                }
            }
            AstNode::WhileLoop { condition, body } => {
                loop {
                    self.execute(condition)?;
                    if self.last_status != 0 {
                        break;
                    }
                    self.execute(body)?;
                    if self.break_flag {
                        self.break_flag = false;
                        break;
                    }
                    if self.continue_flag {
                        self.continue_flag = false;
                        continue;
                    }
                }
            }
            AstNode::CaseStatement { expr, cases } => {
                let expanded_expr = self.expand_word(expr)?;
                if let Some(expr_val) = expanded_expr.first() {
                    for (patterns, body) in cases {
                        for pattern in patterns {
                            if self.glob_match(pattern, expr_val) {
                                self.execute(body)?;
                                return Ok(());
                            }
                        }
                    }
                }
            }
            AstNode::FunctionDef { name, body } => {
                self.functions.insert(name.clone(), (**body).clone());
            }
            AstNode::Subshell(cmd) => {
                // Fork execution (simplified - don't actually fork for now)
                self.execute(cmd)?;
            }
            AstNode::Group(cmd) => {
                self.execute(cmd)?;
            }
            AstNode::Break => {
                self.break_flag = true;
            }
            AstNode::Continue => {
                self.continue_flag = true;
            }
            AstNode::Return => {
                self.return_flag = true;
            }
        }
        Ok(())
    }

    fn execute_command(&mut self, name: &str, args: &[String], redirects: &[Redirect]) -> Result<(), String> {
        // Handle builtins
        match name {
            "echo" => self.builtin_echo(args)?,
            "cd" => self.builtin_cd(args)?,
            "export" => self.builtin_export(args)?,
            "unset" => self.builtin_unset(args)?,
            "set" => self.builtin_set(args)?,
            "alias" => self.builtin_alias(args)?,
            "test" => self.builtin_test(args)?,
            _ => {
                // Check if it's a function
                if let Some(func_body) = self.functions.get(name).cloned() {
                    self.execute(&func_body)?;
                } else {
                    // Execute external command
                    self.execute_external(name, args, redirects)?;
                }
            }
        }
        Ok(())
    }

    fn execute_external(&mut self, cmd: &str, args: &[String], redirects: &[Redirect]) -> Result<(), String> {
        let mut command = Command::new(cmd);

        for arg in args {
            let expanded = self.expand_word(arg)?;
            for e in expanded {
                command.arg(e);
            }
        }

        // Apply redirects
        let mut stdin_redirect = false;
        let mut stdout_redirect = false;
        let mut stderr_redirect = false;

        for redirect in redirects {
            match redirect.from {
                0 => {
                    let file = File::open(&redirect.to)
                        .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stdin(file);
                    stdin_redirect = true;
                }
                1 => {
                    let file = if redirect.append {
                        OpenOptions::new()
                            .append(true)
                            .create(true)
                            .open(&redirect.to)
                    } else {
                        File::create(&redirect.to)
                    }
                    .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stdout(file);
                    stdout_redirect = true;
                }
                2 => {
                    let file = if redirect.append {
                        OpenOptions::new()
                            .append(true)
                            .create(true)
                            .open(&redirect.to)
                    } else {
                        File::create(&redirect.to)
                    }
                    .map_err(|e| format!("cannot open {}: {}", redirect.to, e))?;
                    command.stderr(file);
                    stderr_redirect = true;
                }
                _ => {}
            }
        }

        let output = command
            .output()
            .map_err(|e| format!("{}: {}", cmd, e))?;

        if !stdout_redirect && !output.stdout.is_empty() {
            print!("{}", String::from_utf8_lossy(&output.stdout));
        }
        if !stderr_redirect && !output.stderr.is_empty() {
            eprint!("{}", String::from_utf8_lossy(&output.stderr));
        }

        self.last_status = output.status.code().unwrap_or(1);
        Ok(())
    }

    fn execute_pipe(&mut self, commands: &[AstNode]) -> Result<(), String> {
        if commands.is_empty() {
            return Ok(());
        }

        if commands.len() == 1 {
            return self.execute(&commands[0]);
        }

        // Extract command info from AST nodes
        let mut cmd_specs = Vec::new();
        for cmd in commands {
            if let AstNode::Command { name, args, redirects } = cmd {
                cmd_specs.push((name.clone(), args.clone(), redirects.clone()));
            } else {
                return Err("pipe only works with simple commands".to_string());
            }
        }

        // Create all processes
        let mut children = Vec::new();
        let mut stdin = Stdio::inherit();

        for (i, (name, args, redirects)) in cmd_specs.iter().enumerate() {
            let mut command = Command::new(name);
            command.stdin(stdin);

            // Setup stdout
            if i < cmd_specs.len() - 1 {
                // Pipe to next command
                command.stdout(Stdio::piped());
            } else {
                // Last command inherits stdout
                command.stdout(Stdio::inherit());
            }

            // Expand args
            for arg in args {
                let expanded = self.expand_word(arg)?;
                for e in expanded {
                    command.arg(e);
                }
            }

            let mut child = command
                .spawn()
                .map_err(|e| format!("{}: {}", name, e))?;

            // Get stdout for next command
            if i < cmd_specs.len() - 1 {
                stdin = Stdio::from(child.stdout.take().ok_or("failed to get child stdout")?);
            }

            children.push(child);
        }

        // Wait for all children
        let mut last_status = 0;
        for mut child in children {
            let status = child.wait()
                .map_err(|e| format!("wait error: {}", e))?;
            last_status = status.code().unwrap_or(1);
        }

        self.last_status = last_status;
        Ok(())
    }

