use crate::lexer::{Token, Lexer};
use std::collections::VecDeque;

#[derive(Debug, Clone)]
pub enum AstNode {
    Command {
        name: String,
        args: Vec<String>,
        redirects: Vec<Redirect>,
    },
    Assignment {
        name: String,
        value: String,
    },
    Pipe(Vec<AstNode>),
    And(Vec<AstNode>),
    Or(Vec<AstNode>),
    Sequence(Vec<AstNode>),
    IfStatement {
        condition: Box<AstNode>,
        then_part: Box<AstNode>,
        else_part: Option<Box<AstNode>>,
    },
    ForLoop {
        var: String,
        items: Vec<String>,
        body: Box<AstNode>,
    },
    WhileLoop {
        condition: Box<AstNode>,
        body: Box<AstNode>,
    },
    CaseStatement {
        expr: String,
        cases: Vec<(Vec<String>, AstNode)>,
    },
    FunctionDef {
        name: String,
        body: Box<AstNode>,
    },
    Subshell(Box<AstNode>),
    Group(Box<AstNode>),
    Break,
    Continue,
    Return,
}

#[derive(Debug, Clone)]
pub struct Redirect {
    pub from: i32,
    pub to: String,
    pub append: bool,
}

pub struct Parser {
    tokens: VecDeque<Token>,
}

impl Parser {
    pub fn new(input: &str) -> Self {
        let mut lexer = Lexer::new(input);
        let tokens = lexer.tokenize().unwrap_or_default();
        Parser {
            tokens: tokens.into_iter().collect(),
        }
    }

    pub fn parse(&mut self) -> Result<AstNode, String> {
        self.parse_sequence()
    }

    fn parse_sequence(&mut self) -> Result<AstNode, String> {
        let mut commands = Vec::new();

        loop {
            if self.is_at_end() || self.peek() == &Token::RightParen || self.peek() == &Token::RightBrace {
                break;
            }

            let cmd = self.parse_or()?;
            commands.push(cmd);

            match self.peek() {
                Token::Semicolon => {
                    self.consume();
                    // Skip trailing semicolons
                    while self.peek() == &Token::Semicolon {
                        self.consume();
                    }
                }
                Token::EOF | Token::RightParen | Token::RightBrace => break,
                _ => {}
            }
        }

        if commands.is_empty() {
            Err("unexpected end of input".to_string())
        } else if commands.len() == 1 {
            Ok(commands.into_iter().next().unwrap())
        } else {
            Ok(AstNode::Sequence(commands))
        }
    }

    fn parse_or(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_and()?;

        while self.peek() == &Token::Or {
            self.consume();
            let right = self.parse_and()?;
            left = AstNode::Or(vec![left, right]);
        }

        Ok(left)
    }

    fn parse_and(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_pipe()?;

        while self.peek() == &Token::And {
            self.consume();
            let right = self.parse_pipe()?;
            left = AstNode::And(vec![left, right]);
        }

        Ok(left)
    }

    fn parse_pipe(&mut self) -> Result<AstNode, String> {
        let mut commands = vec![self.parse_term()?];

        while self.peek() == &Token::Pipe {
            self.consume();
            commands.push(self.parse_term()?);
        }

        if commands.len() == 1 {
            Ok(commands.into_iter().next().unwrap())
        } else {
            Ok(AstNode::Pipe(commands))
        }
    }

    fn parse_term(&mut self) -> Result<AstNode, String> {
        match self.peek() {
            Token::If => self.parse_if(),
            Token::For => self.parse_for(),
            Token::While => self.parse_while(),
            Token::Case => self.parse_case(),
            Token::Function => self.parse_function(),
            Token::LeftParen => self.parse_subshell(),
            Token::LeftBrace => self.parse_group(),
            Token::Break => {
                self.consume();
                Ok(AstNode::Break)
            }
            Token::Continue => {
                self.consume();
                Ok(AstNode::Continue)
            }
            Token::Return => {
                self.consume();
                Ok(AstNode::Return)
            }
            _ => self.parse_command(),
        }
    }

    fn parse_if(&mut self) -> Result<AstNode, String> {
        self.expect(Token::If)?;
        let condition = Box::new(self.parse_sequence()?);
        self.expect(Token::Then)?;
        let then_part = Box::new(self.parse_sequence()?);

        let else_part = if self.peek() == &Token::Elif {
            // Handle elif as else if
            Some(Box::new(self.parse_if()?))
        } else if self.peek() == &Token::Else {
            self.consume();
            Some(Box::new(self.parse_sequence()?))
        } else {
            None
        };

        self.expect(Token::Fi)?;

        Ok(AstNode::IfStatement {
            condition,
            then_part,
            else_part,
        })
    }

    fn parse_for(&mut self) -> Result<AstNode, String> {
        self.expect(Token::For)?;

        let var = match self.peek() {
            Token::Word(w) => {
                let v = w.clone();
                self.consume();
                v
            }
            _ => return Err("expected variable name in for loop".to_string()),
        };

        self.expect(Token::In)?;

        let mut items = Vec::new();
        while !matches!(self.peek(), Token::Do | Token::Semicolon | Token::EOF) {
            if let Token::Word(w) = self.peek() {
                items.push(w.clone());
                self.consume();
            } else {
                break;
            }
        }

        self.expect(Token::Do)?;
        let body = Box::new(self.parse_sequence()?);
        self.expect(Token::Done)?;

        Ok(AstNode::ForLoop { var, items, body })
    }

    fn parse_while(&mut self) -> Result<AstNode, String> {
        self.expect(Token::While)?;
        let condition = Box::new(self.parse_sequence()?);
        self.expect(Token::Do)?;
        let body = Box::new(self.parse_sequence()?);
        self.expect(Token::Done)?;

