            Token::Case => self.parse_case(),
            Token::Function => self.parse_function(),
            Token::LeftParen => self.parse_subshell(),
            Token::LeftBrace => self.parse_group(),
            Token::Break => {
                self.consume();
                Ok(AstNode::Break)
            }
            Token::Continue => {
                self.consume();
                Ok(AstNode::Continue)
            }
            Token::Return => {
                self.consume();
