    fn expand_word(&mut self, word: &str) -> Result<Vec<String>, String> {
        let mut result = String::new();
        let chars: Vec<char> = word.chars().collect();
        let mut i = 0;

        while i < chars.len() {
            if chars[i] == '$' && i + 1 < chars.len() {
                if chars[i + 1] == '{' {
                    // ${VAR} expansion
                    i += 2;
                    let mut var_name = String::new();
                    while i < chars.len() && chars[i] != '}' {
                        var_name.push(chars[i]);
                        i += 1;
                    }
                    if i < chars.len() {
                        i += 1; // Skip }
                    }
                    let var_val = self.variables.get(&var_name).cloned().unwrap_or_default();
                    result.push_str(&var_val);
                } else if chars[i + 1] == '(' {
                    // $(...) command substitution
                    i += 2;
                    let mut cmd = String::new();
                    let mut paren_count = 1;
                    while i < chars.len() && paren_count > 0 {
                        if chars[i] == '(' {
                            paren_count += 1;
                        } else if chars[i] == ')' {
                            paren_count -= 1;
                            if paren_count == 0 {
                                break;
                            }
                        }
                        cmd.push(chars[i]);
                        i += 1;
                    }
                    i += 1; // Skip closing )
                    let output = self.run_command_substitution(&cmd)?;
                    result.push_str(&output);
                } else if chars[i + 1].is_alphanumeric() || chars[i + 1] == '_' || chars[i + 1] == '?' {
                    // $VAR or $? expansion
                    i += 1;
                    if chars[i] == '?' {
                        result.push_str(&self.last_status.to_string());
                        i += 1;
                    } else {
                        let mut var_name = String::new();
                        while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                            var_name.push(chars[i]);
                            i += 1;
                        }
                        let var_val = self.variables.get(&var_name).cloned().unwrap_or_default();
                        result.push_str(&var_val);
                    }
                } else {
                    result.push(chars[i]);
                    i += 1;
                }
            } else if chars[i] == '\\' && i + 1 < chars.len() {
                i += 1;
                result.push(chars[i]);
                i += 1;
            } else if chars[i] == '*' || chars[i] == '?' {
                // Glob pattern
                let glob_part = self.collect_glob_pattern(&chars, i);
                return self.glob_expand(&glob_part);
            } else {
                result.push(chars[i]);
                i += 1;
            }
        }

        Ok(vec![result])
    }

    fn collect_glob_pattern(&self, chars: &[char], start: usize) -> String {
        let mut pattern = String::new();
        let mut i = start;

        while i < chars.len() {
            let ch = chars[i];
            if ch.is_whitespace() || ch == '|' || ch == '&' || ch == ';' 
                || ch == '>' || ch == '<' || ch == '(' || ch == ')' {
                break;
            }
            pattern.push(ch);
            i += 1;
        }

        pattern
    }

    fn run_command_substitution(&mut self, cmd: &str) -> Result<String, String> {
        let output = std::process::Command::new("sh")
            .arg("-c")
            .arg(cmd)
            .output()
            .map_err(|e| e.to_string())?;

        let result = String::from_utf8_lossy(&output.stdout).to_string();
        Ok(result.trim_end().to_string())
    }

    fn glob_expand(&self, pattern: &str) -> Result<Vec<String>, String> {
        // Use ls to do the glob expansion
        let output = std::process::Command::new("ls")
            .arg("-d")
            .arg(pattern)
            .output()
            .map_err(|e| e.to_string())?;

        if output.status.success() {
            let result = String::from_utf8_lossy(&output.stdout);
            let matches: Vec<String> = result
                .lines()
                .map(|l| l.to_string())
                .collect();
            if matches.is_empty() {
                Err("no matches".to_string())
            } else {
                Ok(matches)
            }
        } else {
            Err("no matches".to_string())
        }
    }

    fn glob_match(&self, pattern: &str, text: &str) -> bool {
        // Simple glob matching
        let pat_chars: Vec<char> = pattern.chars().collect();
        let text_chars: Vec<char> = text.chars().collect();
        self.glob_match_recursive(&pat_chars, 0, &text_chars, 0)
    }

    fn glob_match_recursive(&self, pattern: &[char], pi: usize, text: &[char], ti: usize) -> bool {
        if pi >= pattern.len() {
            return ti >= text.len();
        }

        match pattern[pi] {
            '*' => {
                if pi + 1 >= pattern.len() {
                    return true;
                }
                for i in ti..=text.len() {
                    if self.glob_match_recursive(pattern, pi + 1, text, i) {
                        return true;
                    }
                }
                false
            }
            '?' => {
                if ti >= text.len() {
                    false
                } else {
                    self.glob_match_recursive(pattern, pi + 1, text, ti + 1)
                }
            }
            _ => {
                if ti >= text.len() || pattern[pi] != text[ti] {
                    false
                } else {
                    self.glob_match_recursive(pattern, pi + 1, text, ti + 1)
                }
            }
        }
    }

