                    return Ok(AstNode::Assignment {
                        name: var_name.to_string(),
                        value: var_value.to_string(),
                    });
                }
            }
        }

        // Parse arguments and redirects
        loop {
            match self.peek() {
                Token::Word(w) => {
                    args.push(w.clone());
                    self.consume();
                }
                Token::GreaterThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 1,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                Token::GreaterGreaterThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 1,
                            to: file.clone(),
                            append: true,
                        });
                        self.consume();
                    }
                }
                Token::LessThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 0,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                Token::GreaterAmpersand => {
