        while self.peek() == &Token::And {
            self.consume();
            let right = self.parse_pipe()?;
            left = AstNode::And(vec![left, right]);
        }

        Ok(left)
    }

    fn parse_pipe(&mut self) -> Result<AstNode, String> {
        let mut commands = vec![self.parse_term()?];

        while self.peek() == &Token::Pipe {
            self.consume();
            commands.push(self.parse_term()?);
        }

        if commands.len() == 1 {
            Ok(commands.into_iter().next().unwrap())
        } else {
            Ok(AstNode::Pipe(commands))
        }
    }

    fn parse_term(&mut self) -> Result<AstNode, String> {
        match self.peek() {
            Token::If => self.parse_if(),
            Token::For => self.parse_for(),
            Token::While => self.parse_while(),
            Token::Case => self.parse_case(),
            Token::Function => self.parse_function(),
            Token::LeftParen => {
                // Look ahead to see if this is a subshell or function def
                let saved_pos = self.tokens.clone();
                self.consume(); // consume (

                if let Token::LeftParen = self.peek() {
                    // It's actually something like "( (" which is subshell with inner group
                    self.tokens = saved_pos;
                    self.parse_subshell()
                } else {
                    // Check if there's a closing ) followed by {
                    let mut temp_pos = self.tokens.clone();
                    let mut depth = 1;
                    while !temp_pos.is_empty() && depth > 0 {
                        match temp_pos.front() {
                            Some(Token::LeftParen) => depth += 1,
                            Some(Token::RightParen) => depth -= 1,
                            Some(Token::EOF) => break,
                            _ => {}
                        }
                        temp_pos.pop_front();
                    }

                    // Now check what follows the closing paren
                    if matches!(temp_pos.front(), Some(Token::LeftBrace)) {
                        // This is a function definition without 'function' keyword
                        self.tokens = saved_pos;
                        self.parse_function_shorthand()
                    } else {
                        // It's a subshell
                        self.tokens = saved_pos;
                        self.parse_subshell()
                    }
                }
            }
            Token::LeftBrace => self.parse_group(),
            Token::Break => {
                self.consume();
                Ok(AstNode::Break)
            }
            Token::Continue => {
                self.consume();
                Ok(AstNode::Continue)
            }
            Token::Return => {
                self.consume();
                Ok(AstNode::Return)
            }
            _ => self.parse_command(),
        }
    }

    fn parse_if(&mut self) -> Result<AstNode, String> {
        self.expect(Token::If)?;

        // Allow statements between if and then
        let condition = Box::new(self.parse_simple_command_or_pipeline()?);

        self.expect(Token::Then)?;
        let then_part = Box::new(self.parse_sequence()?);

        let else_part = if self.peek() == &Token::Elif {
            // Handle elif as else if
            Some(Box::new(self.parse_if()?))
        } else if self.peek() == &Token::Else {
            self.consume();
            Some(Box::new(self.parse_sequence()?))
        } else {
            None
        };

        self.expect(Token::Fi)?;

        Ok(AstNode::IfStatement {
            condition,
            then_part,
            else_part,
        })
    }

    fn parse_simple_command_or_pipeline(&mut self) -> Result<AstNode, String> {
        let mut cmds = vec![self.parse_term()?];

        while self.peek() == &Token::Pipe {
            self.consume();
            cmds.push(self.parse_term()?);
        }

        while self.peek() == &Token::And || self.peek() == &Token::Semicolon {
            self.consume();
            if self.peek() == &Token::Then {
                break;
            }
            cmds.push(self.parse_term()?);
        }

        if cmds.len() == 1 {
            Ok(cmds.into_iter().next().unwrap())
        } else {
            Ok(AstNode::Sequence(cmds))
        }
    }

    fn parse_for(&mut self) -> Result<AstNode, String> {
        self.expect(Token::For)?;

        let var = match self.peek() {
            Token::Word(w) => {
                let v = w.clone();
                self.consume();
                v
            }
            _ => return Err("expected variable name in for loop".to_string()),
        };

        self.expect(Token::In)?;

        let mut items = Vec::new();
        while !matches!(self.peek(), Token::Do | Token::Semicolon | Token::EOF) {
            if let Token::Word(w) = self.peek() {
                items.push(w.clone());
                self.consume();
            } else {
                break;
            }
        }

        // Skip optional semicolon
        if self.peek() == &Token::Semicolon {
            self.consume();
        }

        self.expect(Token::Do)?;
        let body = Box::new(self.parse_sequence()?);
        self.expect(Token::Done)?;

        Ok(AstNode::ForLoop { var, items, body })
    }

    fn parse_while(&mut self) -> Result<AstNode, String> {
        self.expect(Token::While)?;
        let condition = Box::new(self.parse_simple_command_or_pipeline()?);
        self.expect(Token::Do)?;
        let body = Box::new(self.parse_sequence()?);
        self.expect(Token::Done)?;

        Ok(AstNode::WhileLoop { condition, body })
    }

    fn parse_case(&mut self) -> Result<AstNode, String> {
        self.expect(Token::Case)?;

        let expr = match self.peek() {
            Token::Word(w) => {
                let e = w.clone();
                self.consume();
                e
            }
            _ => return Err("expected expression in case statement".to_string()),
        };

        self.expect(Token::In)?;

        // Skip optional newline/semicolon
        while self.peek() == &Token::Semicolon {
            self.consume();
        }

        let mut cases = Vec::new();

        while self.peek() != &Token::Esac && !self.is_at_end() {
            let mut patterns = Vec::new();

            loop {
                if let Token::Word(w) = self.peek() {
                    patterns.push(w.clone());
                    self.consume();
                    if self.peek() == &Token::Or {
                        self.consume();
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }

            // Expect closing paren
            if self.peek() == &Token::LeftParen {
                self.consume();
            }

            let body = self.parse_sequence()?;

            cases.push((patterns, body));

            // Skip semicolons
            while self.peek() == &Token::Semicolon {
                self.consume();
            }
        }

        self.expect(Token::Esac)?;

        Ok(AstNode::CaseStatement { expr, cases })
    }

    fn parse_function(&mut self) -> Result<AstNode, String> {
        self.expect(Token::Function)?;

        let name = match self.peek() {
            Token::Word(w) => {
                let n = w.clone();
                self.consume();
                n
            }
            _ => return Err("expected function name".to_string()),
        };

        // Skip optional parens
        if self.peek() == &Token::LeftParen {
            self.consume();
            self.expect(Token::RightParen)?;
        }

        let body = if self.peek() == &Token::LeftBrace {
            self.consume();
            let b = self.parse_sequence()?;
            self.expect(Token::RightBrace)?;
            Box::new(b)
        } else {
            return Err("expected function body".to_string());
        };

        Ok(AstNode::FunctionDef { name, body })
    }

    fn parse_function_shorthand(&mut self) -> Result<AstNode, String> {
        // Expect name()
        let name = match self.peek() {
            Token::Word(w) => {
                let n = w.clone();
                self.consume();
                n
            }
            _ => return Err("expected function name".to_string()),
        };

        self.expect(Token::LeftParen)?;
        self.expect(Token::RightParen)?;

        let body = if self.peek() == &Token::LeftBrace {
            self.consume();
            let b = self.parse_sequence()?;
            self.expect(Token::RightBrace)?;
            Box::new(b)
        } else {
            return Err("expected function body".to_string());
        };

        Ok(AstNode::FunctionDef { name, body })
    }

    fn parse_subshell(&mut self) -> Result<AstNode, String> {
        self.expect(Token::LeftParen)?;
        let cmd = self.parse_sequence()?;
        self.expect(Token::RightParen)?;
        Ok(AstNode::Subshell(Box::new(cmd)))
    }

    fn parse_group(&mut self) -> Result<AstNode, String> {
        self.expect(Token::LeftBrace)?;
        let cmd = self.parse_sequence()?;
        self.expect(Token::RightBrace)?;
        Ok(AstNode::Group(Box::new(cmd)))
    }

    fn parse_command(&mut self) -> Result<AstNode, String> {
        let mut name = String::new();
        let mut args = Vec::new();
        let mut redirects = Vec::new();

        // Handle builtins or commands
        match self.peek() {
            Token::Word(w) => {
                name = w.clone();
                self.consume();
            }
            _ => return Err("expected command".to_string()),
        }

        // Check if this is a function definition shorthand: name()
        if name.chars().all(|c| c.is_alphanumeric() || c == '_') 
            && self.peek() == &Token::LeftParen {
            // Restore the name and parse as function
            let saved_tokens = self.tokens.clone();
            self.tokens.push_front(Token::Word(name.clone()));
            return self.parse_function_shorthand();
        }

        // Check if this is a variable assignment
        if name.contains('=') {
            if let Some(eq_pos) = name.find('=') {
                let var_name = &name[..eq_pos];
                let var_value = &name[eq_pos + 1..];
                // Check that var_name is a valid identifier
                if var_name.chars().all(|c| c.is_alphanumeric() || c == '_') && 
                   var_name.chars().next().map_or(false, |c| c.is_alphabetic() || c == '_') {
                    return Ok(AstNode::Assignment {
                        name: var_name.to_string(),
                        value: var_value.to_string(),
                    });
                }
            }
        }

        // Parse arguments and redirects
        loop {
            match self.peek() {
                Token::Word(w) => {
                    args.push(w.clone());
                    self.consume();
                }
                Token::GreaterThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 1,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                Token::GreaterGreaterThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 1,
                            to: file.clone(),
                            append: true,
                        });
                        self.consume();
                    }
                }
                Token::LessThan => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 0,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                Token::GreaterAmpersand => {
                    self.consume();
                    if let Token::Word(file) = self.peek() {
                        redirects.push(Redirect {
                            from: 2,
                            to: file.clone(),
                            append: false,
                        });
                        self.consume();
                    }
                }
                _ => break,
            }
        }

        Ok(AstNode::Command { name, args, redirects })
    }

    fn peek(&self) -> &Token {
        self.tokens.front().unwrap_or(&Token::EOF)
    }

    fn consume(&mut self) {
        if !self.is_at_end() {
            self.tokens.pop_front();
        }
    }

    fn expect(&mut self, expected: Token) -> Result<(), String> {
        if std::mem::discriminant(self.peek()) == std::mem::discriminant(&expected) {
            self.consume();
            Ok(())
        } else {
            Err(format!("expected {:?}, got {:?}", expected, self.peek()))
        }
    }

    fn is_at_end(&self) -> bool {
        matches!(self.peek(), Token::EOF)
    }
}
