            let mut body_cmds = Vec::new();
            loop {
                if self.peek() == &Token::Semicolon {
                    // Check if it's ;;
                    let saved = self.tokens.clone();
                    self.consume();
                    if self.peek() == &Token::Semicolon {
                        self.consume();
                        break;
                    } else {
                        // It was just a single semicolon, restore and parse more
                        self.tokens = saved;
                        break;
                    }
                } else if self.peek() == &Token::Esac || self.is_at_end() {
                    break;
                } else {
