                // Empty case body - create a no-op
                AstNode::Command { name: "true".to_string(), args: Vec::new(), redirects: Vec::new() }
            } else if body_cmds.len() == 1 {
                body_cmds.into_iter().next().unwrap()
            } else {
                AstNode::Sequence(body_cmds)
            };

            cases.push((patterns, body));

            // Skip semicolons
            while self.peek() == &Token::Semicolon {
                self.consume();
            }
        }

        self.expect(Token::Esac)?;

        Ok(AstNode::CaseStatement { expr, cases })
    }

